      "pdfPages": [
        203
      ],
      "printedPages": [
        191
      ],
      "section": "appendix-text2-line03",
      "zhContext": "现在什么都看不见。",
      "officialViText": "Hiện tại chị không nhìn thấy gì cả.",
      "originalReportEvidenceIds": [
        "original-detail-pdf203-text2",
        "original-full-pdf203"
      ],
      "sourceReadingMethod": "recovered-literal-original-author-visual-source-record",
