      "pdfPages": [
        203
      ],
      "printedPages": [
        191
      ],
      "section": "appendix-text2-line05",
      "zhContext": "谢谢，希望下午天气能变好。",
      "officialViText": "Em cảm ơn cô, hy vọng chiều nay trời sẽ tốt hơn.",
      "originalReportEvidenceIds": [
        "original-full-pdf203"
      ],
      "sourceReadingMethod": "recovered-literal-original-author-visual-source-record",
      "newPDFReadingClaimed": false
