      "sourceId": "hsk3-official-vi:l18:p197:appendix-text2-line06",
      "sourceIds": [
        "hsk3-official-vi:l18:p197:appendix-text2-line06"
      ],
      "documentSourceId": "hsk3-official-vi-20261004",
      "pdfSHA256": "7e4e6953ff41659af5ec4ca3efd12c7b53e9703f7529ee65d418426afd814951",
      "sourcePDFSHA": "7e4e6953ff41659af5ec4ca3efd12c7b53e9703f7529ee65d418426afd814951",
      "pdfPages": [
        209
      ],
      "printedPages": [
        197
      ],
      "section": "appendix-text2-line06",
      "zhContext": "你先坐着看会儿电视，饺子很快就包好了。",
      "officialViText": "Cháu ngồi xuống xem ti vi một lát đi. Sủi cảo sẽ gói xong ngay bây giờ thôi.",
      "originalReportEvidenceIds": [
        "original-full-pdf209"
      ],
      "sourceReadingMethod": "recovered-literal-original-author-visual-source-record",
